import fs from 'node:fs';
import { createHash, randomUUID } from 'node:crypto';
import { runProcess } from '/mnt/workspace/worktrees/omniagent-plus-v2-guard-sl0-20260915/tests/helpers/guard-process.ts';

const output = new URL('./guard-immediate-parent-exit-r2.json', import.meta.url);
if (fs.existsSync(output)) throw new Error('Preserve previous probe evidence');
const marker = `guard-probe-${randomUUID()}`;
const leaf = 'setInterval(()=>{},1000)';
const identity = pid => {
  try {
    const fields = fs.readFileSync(`/proc/${pid}/stat`, 'utf8').split(') ')[1].split(' ');
    return { start: fields[19], state: fields[0] };
  } catch (error) { if (error.code !== 'ENOENT' && error.code !== 'ESRCH') throw error; return null; }
};
const alive = entry => { const now = identity(entry.pid); return Boolean(now && now.start === entry.start && !['Z', 'X'].includes(now.state)); };
const rows = [];
try {
  for (let trial = 0; trial < 10; trial++) {
    const code = `const{spawn}=require('node:child_process');const c=spawn(process.execPath,['-e',${JSON.stringify(leaf)},${JSON.stringify(marker)}],{detached:true,stdio:'ignore'});console.log(c.pid);c.unref();`;
    const pid = Number(await runProcess(process.execPath, ['-e', code]));
    const entry = { trial, pid, ...identity(pid), escaped: false, cleanup_quiescent: false };
    rows.push(entry);
    entry.escaped = alive(entry);
    if (entry.escaped) {
      const args = fs.readFileSync(`/proc/${pid}/cmdline`, 'utf8').split('\0');
      if (!args.includes(marker) || !args.includes(leaf) || !alive(entry)) throw new Error('Probe custody mismatch');
      process.kill(pid, 'SIGTERM');
    }
    const deadline = Date.now() + 2_000;
    while (alive(entry) && Date.now() < deadline) await new Promise(resolve => setTimeout(resolve, 20));
    entry.cleanup_quiescent = !alive(entry);
    if (!entry.cleanup_quiescent) throw new Error('Probe cleanup did not quiesce');
  }
} finally {
  const helper = fs.readFileSync('/mnt/workspace/worktrees/omniagent-plus-v2-guard-sl0-20260915/tests/helpers/guard-process.ts');
  const result = { at: new Date().toISOString(), control: 'immediate-parent-exit-detached-child', helper_sha256: createHash('sha256').update(helper).digest('hex'), rows, escaped: rows.filter(row => row.escaped).length, all_probe_children_quiescent: rows.every(row => row.cleanup_quiescent), accepted: false };
  fs.writeFileSync(output, JSON.stringify(result, null, 2) + '\n', { flag: 'wx' });
  console.log(JSON.stringify(result));
}
